writing.practiceCode:
use std::mem::{align_of, offset_of, size_of};

#[repr(C)]
struct Header {
    kind: u16,
    length: u32,
}

fn main() {
    println!("{}", offset_of!(Header, length));
    println!("{} {}", size_of::<Header>(), align_of::<Header>());
}
